-    protoList = builtins.split " " nginx.sslProtocols;
-  in !lib.elem proto protoList;
-
-  configFile = pkgs.writeText "nextcloud-coturn.conf" (''
+  configFile = pkgs.writeText "nextcloud-coturn.conf" ''
     no-cli
     simple-log
     log-file=stdout
@@ -38,30 +34,16 @@ let
