-  '' + (if config.nextcloud.useSSL then ''
-    no-udp
-    no-tcp
-    tls-listening-port=${toString cfg.port}
-    cipher-list="${nginx.sslCiphers}"
-    ${optionalString (notProto "TLSv1") "no-tlsv1"}
